    /**
     * Prepare a period date for external return using the period timezone and interval.
     */
    public function prepareDateForPeriod(CarbonPeriod $period, CarbonInterface $date): CarbonInterface
    {
        $dateClass = $period->getDateClass();
        $interval = $period->getDateInterval();
        $hasTimeComponent = $interval->hours !== 0
            || $interval->minutes !== 0
            || $interval->seconds !== 0
            || $interval->microseconds !== 0;

        $made = ([$dateClass, 'make'])($date);

        $periodTimezone = $period->timezone;
        if ($periodTimezone === null) {
            return $made;
        }

        $currentZone = $made->timezone;
        $zone = $hasTimeComponent ? $this : $periodTimezone;

        if ($this->getType() === 3) {
            return $made->setTimezone($this->getName());
        }

        return $made->setTimezone($zone ?? $currentZone);
    }

    private function resolveCarbon(?DateTimeInterface $date): DateTimeInterface
    {
        if ($date) {
            return $date;
        }

        if (isset($this->clock)) {
            return $this->clock->now()->setTimezone($this);
        }

        return Carbon::now($this);
    }
}

